(()=>{function sync(){if(typeof dashboard==='undefined'||!dashboard?.company)return false;window.dashboard=dashboard;const roles=dashboard.company.capabilities||[],isContractor=roles.includes('contractor'),isSubcontractor=roles.includes('subcontractor'),subcontractorOnly=isSubcontractor&&!isContractor,role=isContractor&&isSubcontractor?'Contractor & Subcontractor':isContractor?'Contractor':'Subcontractor',profileTitle=isContractor&&isSubcontractor?'Contractor & Subcontractor Profile':isContractor?'Contractor Profile':'Subcontractor Profile';const badge=document.getElementById('navRole'),profileNav=document.querySelector('[data-view="profile"]'),jobsNav=document.querySelector('[data-view="jobs"]'),postForm=document.getElementById('jobPostForm'),postedJobs=document.getElementById('postedJobsSection');if(badge)badge.textContent=role;if(profileNav)profileNav.textContent=profileTitle;if(subcontractorOnly){if(jobsNav)jobsNav.childNodes[0].textContent='Find Jobs ';[postForm,postedJobs].forEach(element=>{if(!element)return;element.hidden=true;element.style.display='none';element.setAttribute('aria-hidden','true')});postForm?.querySelectorAll('input,textarea,button,select').forEach(field=>field.disabled=true)}return true}if(!sync()){const timer=setInterval(()=>{if(sync())clearInterval(timer)},100);setTimeout(()=>clearInterval(timer),20000)}})();
